public sealed partial class OriginalGame {
 sealed class AudioLevels {public float Master{get;set;}=.75f;public float Effects{get;set;}=.8f;public float Music{get;set;}=.3f;public float Ambience{get;set;}=.45f;public bool Muted{get;set;}}
 sealed class AudioLoop(SoundEffectInstance instance){public SoundEffectInstance Instance=instance;public float Gain;}
 AudioLevels audioLevels=new();readonly Dictionary<string,AudioLoop> audioLoops=[];bool audioPanel;int audioRow,stepSound;string audioZone="",audioJournal="";readonly Dictionary<string,bool> audioDoors=[];readonly Dictionary<string,double> audioAttacks=[];
 string AudioPath=>Path.Combine(options.Root,"UserData","Interface","audio.json");
 void LoadAudio(){try{if(File.Exists(AudioPath))audioLevels=JsonSerializer.Deserialize<AudioLevels>(File.ReadAllText(AudioPath),ContentPackage.Json)??new();}catch(Exception e)when(e is IOException or JsonException){audioLevels=new();}audioLevels.Master=Level(audioLevels.Master);audioLevels.Effects=Level(audioLevels.Effects);audioLevels.Music=Level(audioLevels.Music);audioLevels.Ambience=Level(audioLevels.Ambience);SoundEffect.MasterVolume=audioLevels.Muted?0:audioLevels.Master;if(options.ProductionScene=="audio")audioPanel=true;}
 static float Level(float n)=>float.IsFinite(n)?Math.Clamp(n,0,1):.5f;
 void SaveAudio(){SoundEffect.MasterVolume=audioLevels.Muted?0:audioLevels.Master;try{Directory.CreateDirectory(Path.GetDirectoryName(AudioPath)!);string temp=AudioPath+".writing";File.WriteAllText(temp,JsonSerializer.Serialize(audioLevels,ContentPackage.Json));File.Move(temp,AudioPath,true);}catch(IOException e){Console.Error.WriteLine("Audio settings: "+e.Message);}}
 float Bus(float n)=>audioLevels.Muted?0:n;
 string StepCue(){if(map.Regions.Any(r=>r.Kind=="dungeon"&&r.Contains(state.X,state.Y)))return "step-stone";if(InteriorAt(state.X,state.Y))return "step-wood";if(NearShore(state.X,state.Y))return "step-sand";return package.Terrain[map.Get(state.X,state.Y).Terrain].Visual=="stone"?"step-stone":"step";}
 void PlayProduction(string name,float pan=0){if(name=="step")name=StepCue();if(sounds.TryGetValue("greyhaven.audio."+name,out var sound))sound.Play(Bus(audioLevels.Effects)*.5f,name.StartsWith("step")?(++stepSound%2==0?.035f:-.035f):0,Math.Clamp(pan,-.8f,.8f));}
 void UpdateProductionAudio(float dt){SoundEffect.MasterVolume=audioLevels.Muted?0:audioLevels.Master;if(editor||map.Objects.Count==0)return;bool dock=map.Regions.Any(r=>r.Id=="region.docks"&&r.Contains(state.X,state.Y));string zone=map.Regions.Any(r=>r.Kind=="dungeon"&&r.Contains(state.X,state.Y))?"cellar":map.Regions.Any(r=>r.Safe&&r.Kind=="town"&&r.Contains(state.X,state.Y))&&!dock?"town":"coast";audioZone=zone;string ambience=zone=="cellar"?"ambient-cellar":zone=="town"?"ambient-town":dock||NearShore(state.X,state.Y)?"ambient-coast":"ambient-wind";var desired=new[]{"greyhaven.audio."+ambience,"greyhaven.audio.music-"+zone};
  foreach(string cue in desired)if(!audioLoops.ContainsKey(cue)&&sounds.TryGetValue(cue,out var sound)){var instance=sound.CreateInstance();instance.IsLooped=true;instance.Volume=0;instance.Play();audioLoops[cue]=new(instance);}
  foreach(var pair in audioLoops.ToArray()){var loop=pair.Value;if(state.Paused){if(loop.Instance.State==SoundState.Playing)loop.Instance.Pause();continue;}if(loop.Instance.State==SoundState.Paused)loop.Instance.Resume();loop.Gain=Math.Clamp(loop.Gain+(desired.Contains(pair.Key)?dt:-dt)*.65f,0,1);loop.Instance.Volume=Bus(pair.Key.Contains(".music-")?audioLevels.Music:audioLevels.Ambience)*loop.Gain;if(loop.Gain==0&&!desired.Contains(pair.Key)){loop.Instance.Stop();loop.Instance.Dispose();audioLoops.Remove(pair.Key);}}
 }
 void ProductionSnapshot(bool loaded){foreach(var o in state.World.Objects){var def=map.Objects.FirstOrDefault(d=>d.Id==o.Id);if(def?.Kind is not ("door" or "gate"))continue;if(!loaded&&audioDoors.TryGetValue(o.Id,out bool old)&&old!=o.Active)PlayProduction(def.Kind=="gate"?"gate":"door");audioDoors[o.Id]=o.Active;}foreach(var e in state.Combat.Enemies){if(!loaded&&audioAttacks.TryGetValue(e.Id,out double old)&&old!=e.ActionUntil&&e.ActionUntil>state.ElapsedSeconds&&e.Health>0)PlayProduction(e.Kind=="tidehound"?"hound":e.Kind,Math.Clamp((e.X-state.X-e.Y+state.Y)*.06f,-.8f,.8f));audioAttacks[e.Id]=e.ActionUntil;}
  var j=state.Journal.LastOrDefault();if(j!=null){string key=j.Time+":"+j.Text;if(!loaded&&audioJournal!=""&&key!=audioJournal){if(j.Text.StartsWith("Accepted:")||j.Text.StartsWith("Objectives complete:"))PlayProduction("quest");else if(j.Text.Contains("dressing your wounds"))PlayProduction("bandage");else if(j.Text.Contains("tonic",StringComparison.OrdinalIgnoreCase)&&j.Text.Contains("drank",StringComparison.OrdinalIgnoreCase))PlayProduction("drink");}audioJournal=key;}}
 void DisposeProductionAudio(){SaveAudio();foreach(var l in audioLoops.Values){l.Instance.Stop();l.Instance.Dispose();}audioLoops.Clear();}
 float AudioValue(int row)=>row switch{0=>audioLevels.Master,1=>audioLevels.Effects,2=>audioLevels.Music,_=>audioLevels.Ambience};
 void SetAudioValue(int row,float value){value=Level(value);if(row==0)audioLevels.Master=value;else if(row==1)audioLevels.Effects=value;else if(row==2)audioLevels.Music=value;else audioLevels.Ambience=value;SaveAudio();}
 bool ProductionAudioInput(KeyboardState keys,MouseState mouse){if(Press(keys,Keys.F8)){audioPanel=!audioPanel;return true;}if(!audioPanel)return false;if(Press(keys,Keys.Escape)){audioPanel=false;return true;}if(Press(keys,Keys.M)){audioLevels.Muted=!audioLevels.Muted;SaveAudio();}if(Press(keys,Keys.Up))audioRow=(audioRow+3)%4;if(Press(keys,Keys.Down))audioRow=(audioRow+1)%4;if(Press(keys,Keys.Left))SetAudioValue(audioRow,AudioValue(audioRow)-.05f);if(Press(keys,Keys.Right))SetAudioValue(audioRow,AudioValue(audioRow)+.05f);if(Press(keys,Keys.Enter))PlayProduction("quest");if(mouse.LeftButton==ButtonState.Pressed){for(int row=0;row<4;row++)if(pointer.Y>=270+row*56&&pointer.Y<310+row*56&&pointer.X>=530&&pointer.X<=900){audioRow=row;SetAudioValue(row,(pointer.X-530)/370);}if(oldMouse.LeftButton==ButtonState.Released&&pointer.Y>=510&&pointer.Y<548&&pointer.X>=335&&pointer.X<=600){audioLevels.Muted=!audioLevels.Muted;SaveAudio();}}return true;}
 void DrawProductionAudio(){if(!audioPanel||editor)return;PanelFrame("gump-skills",300,190,680,440);Text("SOUND AND MUSIC [F8]",330,214,Color.Gold);for(int row=0;row<4;row++){int y=278+row*56;Text(new[]{"Master","Effects","Music","Ambience"}[row],335,y,row==audioRow?Color.Gold:Color.White);Rect(530,y,370,18,ColorOf(9,20,23));Rect(530,y,(int)(370*AudioValue(row)),18,ColorOf(173,138,76));Text($"{AudioValue(row)*100:0}%",910,y);}Button(335,510,265,audioLevels.Muted?"UNMUTE [M]":"MUTE [M]");Text("Arrows: adjust | Enter: preview",335,557);Text("Original score | Region: "+audioZone,335,577,ColorOf(166,192,187));}
 bool NearShore(int x,int y){foreach(var d in new[]{new Point(1,0),new Point(-1,0),new Point(0,1),new Point(0,-1)})if(map.Contains(x+d.X,y+d.Y)&&package.Terrain[map.Get(x+d.X,y+d.Y).Terrain].Wet)return true;return false;}
 string TileArt(string original,int x,int y){if(map.Objects.Count==0)return original;if(original=="stone"&&map.Regions.Any(r=>r.Kind=="dungeon"&&r.Contains(x,y)))return "floor-cellar";if(original=="stone"&&InteriorAt(x,y))return "floor-wood";if(original is "grass" or "dirt"&&NearShore(x,y))return "sand";return original;}
 string StaticArt(string original,int x,int y)=>original is "wall-left" or "wall-right"&&map.Regions.Any(r=>r.Id=="region.beacon"&&r.Contains(x,y))&&(x+y)%4==0?"ruin-column":original is "wall-left" or "wall-right"?map.Regions.Any(r=>r.Kind=="dungeon"&&r.Contains(x,y))?(original=="wall-left"?"cellar-left":"cellar-right"):InteriorAt(x,y)?(original=="wall-left"?"timber-left":"timber-right"):original:original;
 string ItemArt(WorldItem item,bool ground=false)=>item.Id==AdventureRules.Heart?"lantern-heart":item.Id==AdventureRules.Mail?"letter-packet":WorldAuthoring.IsKey(package,item.Id)?"vault-key":ground?itemDefs[item.Definition].GroundVisual:itemDefs[item.Definition].InventoryVisual;
 string NpcArt(MapObject npc)=>package.AdventureCatalog.Routines.Any(r=>r.NpcId==npc.Id)&&npc.Actor=="humanoid-h1-s0-b0"?(npc.Id.Sum(c=>(int)c)%2==0?"resident-linen":"resident-moss"):npc.Actor;
 void PanelFrame(string image,int x,int y,int w,int h){Rect(x+3,y+3,w-6,h-6,ColorOf(22,37,41,250));if(!textures.TryGetValue(package.ImagePath(image),out var t)){Rect(x,y,w,h,ColorOf(25,39,43));return;}int s=18;for(int yy=0;yy<3;yy++)for(int xx=0;xx<3;xx++){int sx=xx==0?0:xx==1?s:t.Width-s,sy=yy==0?0:yy==1?s:t.Height-s,sw=xx==1?t.Width-2*s:s,sh=yy==1?t.Height-2*s:s;int dx=x+(xx==0?0:xx==1?s:w-s),dy=y+(yy==0?0:yy==1?s:h-s),dw=xx==1?w-2*s:s,dh=yy==1?h-2*s:s;batch.Draw(t,new Rectangle(dx,dy,dw,dh),new Rectangle(sx,sy,sw,sh),Color.White);}}
 void DrawSpriteEffect(string kind,Vector2 at,float progress,float scale=1,float angle=0){if(kind is "ward" or "gate" or "bind")at.Y+=25;string name=kind switch{"ember"=>"fx-ember","venom"=>"fx-venom","storm"=>"fx-storm","heal"=>"fx-heal","ward"=>"fx-ward","gate"=>"fx-gate","bind"=>"fx-bind",_=>"fx-quest"};var t=textures[package.ImagePath(name)];float pulse=(.65f+MathF.Sin(progress*MathF.PI)*.4f)*scale;batch.Draw(t,at,null,Color.White*(1-progress*.55f),kind is "ember" or "venom"?angle+MathF.PI:0,new Vector2(t.Width/2f,t.Height/2f),pulse,SpriteEffects.None,0);}
 void DrawProductionReview(){if(options.ProductionScene!="bestiary"||editor)return;PanelFrame("gump-quests",150,140,980,575);Text("GREYHAVEN | PRODUCTION ART",225,167,Color.Gold);Text("Five enemy silhouettes | Eight-facing shared cutout rigs",185,197);string[] actors=["tidehound","shore-raider","reef-slinger","salt-hexer","brineguard"];for(int i=0;i<actors.Length;i++){Actor(actors[i],3,"walk",255+i*180,418,1.45f);Text(actors[i],190+i*180,437,Color.Gold);}string[] items=["bandage","lantern-heart","vault-key","greatblade","letter-packet","satchel","gate-rune","corpse-marker"];for(int i=0;i<items.Length;i++)Image(items[i],205+i*110,492,54,54);string[] effects=["ember","venom","storm","ward","heal","gate","bind","quest"];for(int i=0;i<effects.Length;i++)DrawSpriteEffect(effects[i],new(232+i*110,610),.45f,.7f);Text("Original source sheets, cutout extraction, and deterministic animation",185,676,ColorOf(180,201,191));}
 int productionStep;bool productionDone;double productionSeconds;
 void RunProductionSmoke(float dt){if(!options.ProductionSmoke||productionDone)return;productionSeconds+=dt;if(productionSeconds>25)throw new ContentException("Production smoke timed out: "+productionStep);if(session?.Busy!=false||productionSeconds<2)return;void Require(bool ok,string why){if(!ok)throw new ContentException("Production route: "+why);}switch(productionStep){case 0:Require(sounds.Count==39&&audioLoops.Count>=2,"all cues load and zone loops start");SetAudioValue(0,.6f);SetAudioValue(2,.2f);LoadAudio();Require(audioLevels.Master==.6f&&audioLevels.Music==.2f,"audio levels persist");foreach(var cue in new[]{"door","bandage","coins","ember","venom","storm","hound","brineguard"})PlayProduction(cue);SendInventory(new(){Type="pause"});break;case 1:Require(state.Paused,"host pauses");UpdateProductionAudio(dt);Require(audioLoops.Values.All(l=>l.Instance.State==SoundState.Paused),"loops pause");SendInventory(new(){Type="pause",Destination="resume"});break;case 2:Require(!state.Paused,"host resumes");UpdateProductionAudio(dt);Require(audioLoops.Values.All(l=>l.Instance.State==SoundState.Playing),"loops resume");audioLevels.Muted=true;UpdateProductionAudio(dt);Require(SoundEffect.MasterVolume==0&&audioLoops.Values.All(l=>l.Instance.Volume==0),"mute bus");audioLevels.Muted=false;SaveAudio();audioPanel=true;productionDone=true;Console.WriteLine("Native production routes: 39 decoded cues, region music/ambience, persistent bus levels, pause/resume and mute passed. Zone: "+audioZone+".");break;}productionStep++;}
}
